        const g = ctx.createLinearGradient(0, 0, 0, H * .75); g.addColorStop(0, `rgba(120,200,230,${.06 + .03 * Math.sin(t / 4000 + i)})`); g.addColorStop(1, 'rgba(120,200,230,0)');
