      S.clouds = Array.from({ length: 16 }, (_, i) => ({ x: rnd(-W * .3, W), y: rnd(H * .1, H * .95), w: rnd(W * .25, W * .6), h: rnd(30, 90), s: rnd(.08, .35) * (i % 3 ? 1 : 1.6), a: rnd(.25, .6), front: i % 4 === 0 }));
