      [[-120, 30], [-95, 55], [-60, 85], [-30, 120], [0, 140], [28, 105], [60, 75], [92, 50], [122, 28]].forEach(([dx, h]) => { c.fillRect(cx + dx - 10, 150 - h, 20, h); c.beginPath(); c.ellipse(cx + dx, 150 - h, 10, 4, 0, 0, 6.28); c.fill(); });
