// alien glyphs for the hunter readout: strokes on two stacked eight-point stars, made up at random
function S_glyph() { const g = []; for (let n = 0; n < 2; n++) { const k = 2 + ((Math.random() * 3) | 0); const pick = new Set(); while (pick.size < k) pick.add((Math.random() * 8) | 0); pick.forEach(d => g.push([n, d])); } return g; }
function drawGlyph(ctx, g, x, y, s, a) {
  ctx.globalAlpha = a; ctx.lineWidth = 2.2;
  g.forEach(([n, d]) => { const cy = y + n * s * 2.1, ang = d * Math.PI / 4 - Math.PI / 2; ctx.beginPath(); ctx.moveTo(x + Math.cos(ang) * s * .25, cy + Math.sin(ang) * s * .25); ctx.lineTo(x + Math.cos(ang) * s, cy + Math.sin(ang) * s); ctx.stroke(); });
}
function triBars(ctx, x, y, r, a, col) {                // three bars that form a triangle around (x, y)
  ctx.globalAlpha = a; ctx.strokeStyle = col; ctx.lineWidth = Math.max(2, r / 14); ctx.lineCap = 'butt';
  const p = [0, 1, 2].map(i => [x + Math.cos(-Math.PI / 2 + i * 2.094) * r, y + Math.sin(-Math.PI / 2 + i * 2.094) * r]);
  for (let i = 0; i < 3; i++) { const A = p[i], B = p[(i + 1) % 3], m = .18; ctx.beginPath(); ctx.moveTo(A[0] + (B[0] - A[0]) * m, A[1] + (B[1] - A[1]) * m); ctx.lineTo(A[0] + (B[0] - A[0]) * (1 - m), A[1] + (B[1] - A[1]) * (1 - m)); ctx.stroke(); }
}
let scn = null;
function stopScene() { if (scn) { cancelAnimationFrame(scn.raf); window.removeEventListener('resize', scn.resize); scn.cv.remove(); scn = null; } const pb = document.getElementById(OUR + '-pipbtn'); if (pb) pb.remove(); const cl = document.getElementById(OUR + '-curve'); if (cl) cl.remove(); }
function startScene() {
  if (monoPreview) return;                           // v6.12: waits for the exact colors (the quick filter would flip it)
  const name = T && animOn() && !fxOff && window.top === window ? Object.keys(SCENES).find(n => hasFx(n)) || '' : '';
  if (!name) { stopScene(); return; }
  const sig = name + '|' + T.name;
  if (scn && scn.sig === sig) return;
  stopScene();
  const sc = SCENES[name], cv = document.createElement('canvas');
  cv.id = OUR + '-scene';
  cv.style.cssText = 'position:fixed;left:0;top:0;width:100vw;height:100vh;pointer-events:none;z-index:' + (sc.over ? 2147483600 : -1);
  document.documentElement.appendChild(cv);
  const ctx = cv.getContext('2d'), step = 1000 / (sc.fps || 20);
  let S = {}, last = 0;
  function resize() { const t0 = performance.now(); cv.width = innerWidth; cv.height = innerHeight; S = { W: cv.width, H: cv.height }; try { sc.init(S, ctx); } catch (e) { console.warn('[Page Themes] effect', name, e); } busy(performance.now() - t0); }
  function frame(t) {
    scn.raf = requestAnimationFrame(frame);
    if (!viewing()) { if (sc.over && !S.cleared) { ctx.clearRect(0, 0, S.W, S.H); S.cleared = true; S.drawn = false; } return; }   // never leave a glitch frozen on screen
    if (t - last < step) return;
    last = t; S.cleared = false;
    const t0 = performance.now();
    try { sc.draw(ctx, S, t); } catch (e) { console.warn('[Page Themes] effect', name, 'stopped:', e); stopScene(); return; }
    busy(performance.now() - t0);
  }
  scn = { sig, cv, raf: 0, resize, S: null };
  window.addEventListener('resize', resize); resize();
  if (!sc.still) scn.raf = requestAnimationFrame(frame);
}

// ---------- HUD readout (Colonial Marine): live info from the page you are on ----------
// Reads only what is already on screen: RO number, vehicle, VIN. Clicks pass through it.
let hudEl = null, hudTimer = 0, hudClock = 0;
function readPageInfo() {
  const info = { ro: '', veh: '', vin: '', stock: '' };
  const tk = document.querySelector('[data-test-id="undefined-modelButton"] span');   // Tekion vehicle line
  if (tk) info.veh = tk.textContent.trim();
  const els = document.querySelectorAll('span,div,td,a,h1,h2,h3,p,input,b,strong');
  for (let i = 0, n = Math.min(els.length, 4000); i < n; i++) {
    const el = els[i]; if (el.closest && el.closest('[id^="' + OUR + '"]')) continue;
    const txt = (el.tagName === 'INPUT' ? el.value : (el.childElementCount === 0 ? el.textContent : '')) || '';
    const t = txt.trim(); if (!t || t.length > 60) continue;
    if (!info.vin && /^[A-HJ-NPR-Z0-9]{17}$/.test(t)) info.vin = t;
    if (!info.ro) { const m = t.match(/^(?:RO\s*#?\s*)?(7\d{6})$/i); if (m) info.ro = m[1]; }
    if (!info.veh) { const m = t.match(/^((?:19|20)\d{2})\s+([A-Za-z][A-Za-z-]+)(\s+[A-Za-z0-9-]+){1,3}$/); if (m) info.veh = t; }
    if (!info.stock && /^\d{1,2}[A-Z]\d{4}[A-Z]?$/.test(t)) info.stock = t;
    if (info.vin && info.ro && info.veh && info.stock) break;
  }
  if (!info.ro) { const m = (document.title + ' ' + location.href).match(/\b(7\d{6})\b/); if (m) info.ro = m[1]; }
  return info;
}
function stopHudInfo() { clearInterval(hudTimer); clearInterval(hudClock); if (hudEl) hudEl.remove(); hudEl = null; }
function startHudInfo() {
  if (!T || !hasFx('hud') || window.top !== window || !document.body) { stopHudInfo(); return; }
  if (hudEl && hudEl.isConnected) return;
  const c = T.fxColor || '#f2a900';
  hudEl = document.createElement('div'); hudEl.id = OUR + '-hudinfo';
  hudEl.style.cssText = `position:fixed;right:16px;top:140px;z-index:2147483640;pointer-events:none;font:12px/1.55 Consolas,monospace;color:${c};`
    + `background:rgba(0,0,0,.45);border-left:3px solid ${c};padding:8px 12px;letter-spacing:.06em;text-transform:uppercase;text-shadow:0 0 6px ${rgba(c, .6)}`;
  document.documentElement.appendChild(hudEl);
  const site = /tekion/.test(HOST) ? 'TEKION' : /reconvision/.test(HOST) ? 'RECONVISION' : /partstech/.test(HOST) ? 'PARTSTECH' : /teams/.test(HOST) ? 'TEAMS' : HOST.split('.')[0].toUpperCase();
  let info = readPageInfo();
  const draw = () => {
    if (!hudEl) return;
    const now = new Date(), clock = now.toTimeString().slice(0, 8);
    const lines = ['◢ M-TRAK HUD  ' + site, 'RO   ' + (info.ro || '------'), 'VEH  ' + (info.veh || 'NO TARGET').slice(0, 34), 'VIN  ' + (info.vin || '-----------------'), 'T+   ' + clock];
    hudEl.textContent = '';
    lines.forEach((l, i) => { const d = document.createElement('div'); d.textContent = l; if (i === 0) d.style.opacity = '.7'; hudEl.appendChild(d); });
  };
  draw();
  hudTimer = setInterval(() => { if (!document.hidden) { info = readPageInfo(); draw(); } }, 3000);   // page info every 3 s
  hudClock = setInterval(() => { if (!document.hidden) draw(); }, 1000);                              // clock every second
}

// ---------- laser line that travels around a button while you hover it ----------
// A separate see-through layer is drawn over the button; the button itself is not changed.
const BTN_SEL = 'button,[role="button"],input[type="button"],input[type="submit"],a.btn,[data-wr-bg="accent"]';
let laserEl = null, laserTarget = null, laserRaf = 0;
function hideLaser() {
  laserTarget = null; cancelAnimationFrame(laserRaf);
  if (laserEl) laserEl.style.display = 'none';
}
function showLaser(b) {
  if (!laserEl) { laserEl = document.createElement('div'); laserEl.id = OUR + '-laser'; document.documentElement.appendChild(laserEl); }
  if (!laserEl.isConnected) document.documentElement.appendChild(laserEl);
  laserTarget = b;
  const mode = T.hover || 'laser';
  const rad = parseFloat(getComputedStyle(b).borderTopLeftRadius) || 0;
  laserEl.dataset.mode = mode;
  laserEl.style.borderRadius = mode === 'drip' ? '0' : mode === 'shine' ? rad + 'px' : (rad + 3) + 'px';
  laserEl.style.animation = 'none'; void laserEl.offsetWidth; laserEl.style.animation = '';   // restart (drip runs once)
  laserEl.style.display = 'block';
  cancelAnimationFrame(laserRaf);
  const pad = mode === 'sparkle' ? 10 : mode === 'shine' ? 0 : 3;
  const follow = () => {                         // keep it on the button while scrolling
    if (!laserTarget || !laserTarget.isConnected) return hideLaser();
    const r = laserTarget.getBoundingClientRect();
    if (mode === 'drip') {                       // drips hang from the bottom edge
      laserEl.style.left = r.left + 'px'; laserEl.style.top = (r.bottom - 3) + 'px';
      laserEl.style.width = r.width + 'px'; laserEl.style.height = '38px';
    } else {
      laserEl.style.left = (r.left - pad) + 'px'; laserEl.style.top = (r.top - pad) + 'px';
      laserEl.style.width = (r.width + pad * 2) + 'px'; laserEl.style.height = (r.height + pad * 2) + 'px';
    }
    laserRaf = requestAnimationFrame(follow);
  };
  follow();
}
document.addEventListener('mouseover', e => {
  if (!T || !animOn()) { if (laserTarget) hideLaser(); return; }
  const b = e.target && e.target.closest ? e.target.closest(BTN_SEL) : null;
  if (!b || b.closest('[id^="' + OUR + '"]')) { if (laserTarget && !laserTarget.contains(e.target)) hideLaser(); return; }
  if (b !== laserTarget) showLaser(b);
}, true);
document.addEventListener('mouseout', e => {               // mouse left the button (not just moved onto its text)
  if (laserTarget && !(e.relatedTarget && laserTarget.contains(e.relatedTarget)) && laserTarget.contains(e.target)) hideLaser();
}, true);

// Re-apply everything (after any settings change)
function refresh(rescan) {
  cfg = siteCfg();
  T = allThemes()[activeThemeId()] || null;
  applyStyle();
  if (!document.body) return;
  startFx(); startMesh(); startHudInfo();
  if (!T) { stopObserver(); unscanAll(); return; }
  if (rescan) { unscanAll(); work = []; pendingDecisions = []; scan([document.documentElement], true); }
  startObserver();
}

// ---------- start ----------
applyStyle();                                   // early: avoids a white flash
function onReady() { if (T) { scan([document.documentElement], false); startObserver(); startFx(); startMesh(); startHudInfo(); } }
if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', onReady, { once: true });
else onReady();

if (window.top !== window) return;              // menu + panel only in the main window
GM_registerMenuCommand('🎨 Themes & colors…', () => {
  try { openPanel(); }
  catch (e) { console.error('[Page Themes] could not open the panel:', e); alert('Page Themes could not open on this page.\n\nError: ' + (e && e.message ? e.message : e) + '\n\nPlease send a screenshot of this message.'); }
});
if (dailyState().on) GM_registerMenuCommand('⏭ Skip today\'s theme', () => { skipDaily(); if (host) openPanel(); });

// ---------- settings panel (shadow DOM so page styles can't touch it) ----------
let host = null;
function esc(s) { return String(s).replace(/[&<>"]/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c])); }
function openPanel() {
  if (host) { host.remove(); host = null; }
  host = document.createElement('div');
  host.id = OUR + '-host';
  host.style.cssText = 'all:initial;position:fixed;top:12px;right:12px;z-index:2147483647';
  const pos = load('panel_pos', null);           // where the user last dragged it
  if (pos) placePanel(pos.x, pos.y);
  const root = host.attachShadow({ mode: 'open' });
  document.documentElement.appendChild(host);
  render(root);
}
function placePanel(x, y) {                       // keep at least the header on screen
  x = Math.max(0, Math.min(x, window.innerWidth - 120));
  y = Math.max(0, Math.min(y, window.innerHeight - 40));
  Object.assign(host.style, { left: x + 'px', top: y + 'px', right: 'auto' });
}
function makeDraggable(root) {
  const handle = root.querySelector('#drag');
  handle.onpointerdown = e => {
    if (e.target.closest('button')) return;
    e.preventDefault();
    const r = host.getBoundingClientRect(), dx = e.clientX - r.left, dy = e.clientY - r.top;
    const move = ev => placePanel(ev.clientX - dx, ev.clientY - dy);
    const up = () => {
      window.removeEventListener('pointermove', move, true); window.removeEventListener('pointerup', up, true);
      const r2 = host.getBoundingClientRect(); save('panel_pos', { x: r2.left, y: r2.top });
    };
    window.addEventListener('pointermove', move, true); window.addEventListener('pointerup', up, true);
  };
}
// ---------- undo (steps back one change at a time, until the page is reloaded) ----------
const undoStack = [];
function snapshot() {
  undoStack.push(JSON.stringify({ site: getSites()[HOST] || null, custom: customThemes(), daily: dailyState() }));
  if (undoStack.length > 40) undoStack.shift();
}
function undoLast() {
  const raw = undoStack.pop(); if (!raw) return false;
  const st = JSON.parse(raw), sites = getSites();
  if (st.site) sites[HOST] = st.site; else delete sites[HOST];
  save('sites', sites); save('custom_themes', st.custom); save('daily', st.daily);
  refresh(true); return true;
}
// Save a change to the current theme. Editing a suggested theme makes a "My ..." copy.
function updateTheme(changes) {
  snapshot();
  const c = customThemes();
  const cur = activeThemeId();
  let id = cur;
  if (PRESETS[id]) {
    id = 'my_' + id;
    if (!c[id]) c[id] = Object.assign({}, PRESETS[cur], { name: 'My ' + PRESETS[cur].name });
  }
  c[id] = Object.assign({}, c[id], changes);
  try { save('custom_themes', c); }
  catch (e) { alert('Could not save (picture too big?). Try a smaller picture.'); return false; }
  const switched = cur !== id;
  setActiveTheme(id); refresh(false);
  return switched;
}
// Shrink an uploaded picture so it saves fast and small (max 1920px wide, JPEG).
function shrinkImage(file, cb) {
  const fr = new FileReader();
  fr.onload = () => {
    const img = new Image();
    img.onload = () => {
      const scale = Math.min(1, 1920 / img.width, 1200 / img.height);
      const cv = document.createElement('canvas');
      cv.width = Math.round(img.width * scale); cv.height = Math.round(img.height * scale);
      cv.getContext('2d').drawImage(img, 0, 0, cv.width, cv.height);
      let q = 0.82, url = cv.toDataURL('image/jpeg', q);
      while (url.length > 900000 && q > 0.4) { q -= 0.1; url = cv.toDataURL('image/jpeg', q); }
      cb(url);
    };
    img.onerror = () => cb(null);               // not a picture, or this site blocks pictures
    img.src = fr.result;
  };
  fr.readAsDataURL(file);
}
// Can this site show this picture? (Some sites block outside pictures.)
function testImage(url, cb) {
  const m = /^url\("(.*)"\)$/.exec(url);
  if (!m) { cb(true); return; }
  const img = new Image();
  img.onload = () => cb(true); img.onerror = () => cb(false);
  img.src = m[1];
}
