    function nativeSet(el, value) {
        const proto = el.tagName === 'TEXTAREA'
            ? window.HTMLTextAreaElement.prototype
            : window.HTMLInputElement.prototype;
        const setter = Object.getOwnPropertyDescriptor(proto, 'value').set;
        setter.call(el, value);
        el.dispatchEvent(new Event('input', { bubbles: true }));
        el.dispatchEvent(new Event('change', { bubbles: true }));
        el.dispatchEvent(new FocusEvent('blur', { bubbles: true }));
        el.dispatchEvent(new FocusEvent('focus', { bubbles: true }));
    }

    let filling = false;

    document.addEventListener('focusin', (e) => {
        const el = e.target;
        const isMatch = el.tagName === 'TEXTAREA' &&
            (el.getAttribute('data-field-name') === 'partNumber' ||
             el.id.includes('part_number') ||
             el.placeholder === 'Add Part#');
        if (el.tagName === 'TEXTAREA') {
            console.log('[RV Paste] Focused a TEXTAREA -- id:', el.id, '-- data-field-name:', el.getAttribute('data-field-name'), '-- placeholder:', el.placeholder, '-- matched:', isMatch);
        }
        if (
            isMatch
        ) {
            if (filling) { console.log('[RV Paste] Ignored -- already filling'); return; }
            // v6.06: only fill an EMPTY part# box. Coming back to the RV window puts the cursor back in the
            // box you used last (the first part's), which fired this again and replaced the first part with
            // the second one. A box that already has a part # is never overwritten now.
            if ((el.value || '').trim()) { console.log('[RV Paste] Skipped -- this part# box already has', JSON.stringify(el.value.trim()), '(never overwritten)'); return; }
            let { part, price } = getSellingClip();
            console.log('[RV Paste] selling slot:', part, price);
            if (!part) {
                const fallback = getClip();
                part = fallback.part; price = fallback.price;
                console.log('[RV Paste] selling slot empty, fallback slot:', part, price);
            }
            if (!part) { console.log('[RV Paste] Both slots empty -- nothing to paste'); return; }
            filling = true;
            console.log('[RV Paste] Setting part# field to:', part);
            nativeSet(el, part);

            // Small easter egg: every 15th successful RV paste, a little ship
            // flies across the screen. Purely cosmetic, easy to remove later —
            // just delete this block and the spawnXWingEasterEgg function.
            const rvPasteCount = (parseInt(GM_getValue('clip_rv_paste_count', '0'), 10) || 0) + 1;
            GM_setValue('clip_rv_paste_count', String(rvPasteCount));
            if (rvPasteCount % 15 === 0) {
                spawnXWingEasterEgg();
            }

            setTimeout(() => {
                // v5.86: the old lookup fell back to document.querySelector(...)
                // whenever the row-scoped search came up empty -- and that
                // returns the FIRST price input on the whole page, i.e. the
                // previously pasted part's row. That is exactly the "each new
                // paste changes the previous part's price" bug. Now: climb
                // from this part# field to the nearest ancestor that contains
                // exactly ONE part_price input (that's this part's own row,
                // whatever its tag/structure), and never fall back to a
                // page-wide first match -- if it can't be found, skip the
                // price rather than overwrite another row.
                let row = el.parentElement;
                let priceInput = null;
                while (row && row !== document.body) {
                    const found = row.querySelectorAll('input[id*="part_price"], input[data-field-name="partPrice"]');
                    if (found.length === 1) { priceInput = found[0]; break; }
                    if (found.length > 1) break; // climbed past this row into a multi-row container
                    row = row.parentElement;
                }
                console.log('[RV Paste] row found:', !!row, '-- priceInput found:', !!priceInput, priceInput ? '-- id: ' + priceInput.id : '');
                if (priceInput && price) {
                    console.log('[RV Paste] Setting price field to:', price);
                    nativeSet(priceInput, price);
                    GM_setValue('clip_selling_price', '');
                    GM_setValue('clip_price', '');
                } else if (!priceInput) {
                    console.log('[RV Paste] NO PRICE FIELD FOUND -- part# alone was set, price left untouched');
                }
                GM_setValue('clip_selling_part', '');
                GM_setValue('clip_part', '');
                setTimeout(() => { filling = false; }, 800);
            }, 300);
        }
    }, true);

