        pillContainer.appendChild(btn24);

        const btnQuote = document.createElement('button');
        btnQuote.id = 'rv-btn-quote';
        btnQuote.className = 'rv-bucket-btn';
        btnQuote.textContent = 'QUOTE';
        pillContainer.appendChild(btnQuote);

